// ImGuizmo takes its matrices as float[16] in column-major order, as OpenGL does.
// Python passes them as 4x4 arrays indexed [row, column], whatever their memory
// order: the translation of a model matrix is matrix[:3, 3]. The matrices that
// ImGuizmo modifies are written back into the arrays, which must thus be float32
// (other arrays are converted).
using Matrix = nb::ndarray<const float, nb::shape<4, 4>, nb::device::cpu>;
using MutableMatrix = nb::ndarray<float, nb::shape<4, 4>, nb::device::cpu>;
using Matrices = nb::ndarray<const float, nb::shape<-1, 4, 4>, nb::device::cpu>;
using Vec3 = std::array<float, 3>;

struct ColumnMajor {
    float m[16] = {};

    ColumnMajor() = default;

    template <typename Array> explicit ColumnMajor(const Array& array)
    {
        auto v = array.view();
        for (size_t row = 0; row < 4; ++row)
            for (size_t column = 0; column < 4; ++column)
                m[column * 4 + row] = v(row, column);
    }

    void store(MutableMatrix& array) const
    {
        auto v = array.view();
        for (size_t row = 0; row < 4; ++row)
            for (size_t column = 0; column < 4; ++column)
                v(row, column) = m[column * 4 + row];
    }
};

static std::vector<float> column_major(const Matrices& matrices)
{
    auto v = matrices.view();
    std::vector<float> m(v.shape(0) * 16);
    for (size_t i = 0; i < v.shape(0); ++i)
        for (size_t row = 0; row < 4; ++row)
            for (size_t column = 0; column < 4; ++column)
                m[i * 16 + column * 4 + row] = v(i, row, column);
    return m;
}

static nb::tuple tuple3(const float* v) { return nb::make_tuple(v[0], v[1], v[2]); }

// Declared in the stubs by generate.py (add_imguizmo_matrix_functions)
void bind_matrix_functions(nb::module_& m)
{
    m.def("manipulate",
        [](const Matrix& view, const Matrix& projection, ImGuizmo::OPERATION operation, ImGuizmo::MODE mode,
           MutableMatrix matrix, MutableMatrix delta_matrix, std::optional<Vec3> snap,
           std::optional<std::array<float, 6>> local_bounds, std::optional<Vec3> bounds_snap) {
            ColumnMajor m(matrix), delta;
            bool changed = ImGuizmo::Manipulate(ColumnMajor(view).m, ColumnMajor(projection).m, operation, mode, m.m,
                                                delta_matrix.is_valid() ? delta.m : nullptr,
                                                snap ? snap->data() : nullptr,
                                                local_bounds ? local_bounds->data() : nullptr,
                                                bounds_snap ? bounds_snap->data() : nullptr);
            m.store(matrix);
            if (delta_matrix.is_valid())
                delta.store(delta_matrix);
            return changed;
        },
        nb::arg("view"), nb::arg("projection"), nb::arg("operation"), nb::arg("mode"), nb::arg("matrix").noconvert(),
        nb::arg("delta_matrix").noconvert().none() = nb::none(), nb::arg("snap") = nb::none(),
        nb::arg("local_bounds") = nb::none(), nb::arg("bounds_snap") = nb::none());

    m.def("view_manipulate",
        [](MutableMatrix view, float length, ImVec2 position, ImVec2 size, ImU32 background_color) {
            ColumnMajor v(view);
            ImGuizmo::ViewManipulate(v.m, length, position, size, background_color);
            v.store(view);
        },
        nb::arg("view").noconvert(), nb::arg("length"), nb::arg("position"), nb::arg("size"),
        nb::arg("background_color"));
    m.def("view_manipulate",
        [](MutableMatrix view, const Matrix& projection, ImGuizmo::OPERATION operation, ImGuizmo::MODE mode,
           MutableMatrix matrix, float length, ImVec2 position, ImVec2 size, ImU32 background_color) {
            ColumnMajor v(view), m(matrix);
            ImGuizmo::ViewManipulate(v.m, ColumnMajor(projection).m, operation, mode, m.m, length, position, size,
                                     background_color);
            v.store(view);
            m.store(matrix);
        },
        nb::arg("view").noconvert(), nb::arg("projection"), nb::arg("operation"), nb::arg("mode"),
        nb::arg("matrix").noconvert(), nb::arg("length"), nb::arg("position"), nb::arg("size"),
        nb::arg("background_color"));

    m.def("decompose_matrix_to_components",
        [](const Matrix& matrix) {
            float translation[3], rotation[3], scale[3];
            ImGuizmo::DecomposeMatrixToComponents(ColumnMajor(matrix).m, translation, rotation, scale);
            return nb::make_tuple(tuple3(translation), tuple3(rotation), tuple3(scale));
        },
        nb::arg("matrix"));
    m.def("recompose_matrix_from_components",
        [](Vec3 translation, Vec3 rotation, Vec3 scale, MutableMatrix matrix) {
            ColumnMajor m(matrix);
            ImGuizmo::RecomposeMatrixFromComponents(translation.data(), rotation.data(), scale.data(), m.m);
            m.store(matrix);
        },
        nb::arg("translation"), nb::arg("rotation"), nb::arg("scale"), nb::arg("matrix").noconvert());

    m.def("draw_axes",
        [](const Matrix& view, const Matrix& projection, const Matrices& matrices) {
            std::vector<float> m = column_major(matrices);
            ImGuizmo::DrawAxes(ColumnMajor(view).m, ColumnMajor(projection).m, m.data(), (int)matrices.shape(0));
        },
        nb::arg("view"), nb::arg("projection"), nb::arg("matrices"));
    m.def("draw_cubes",
        [](const Matrix& view, const Matrix& projection, const Matrices& matrices) {
            std::vector<float> m = column_major(matrices);
            ImGuizmo::DrawCubes(ColumnMajor(view).m, ColumnMajor(projection).m, m.data(), (int)matrices.shape(0));
        },
        nb::arg("view"), nb::arg("projection"), nb::arg("matrices"));
    m.def("draw_grid",
        [](const Matrix& view, const Matrix& projection, const Matrix& matrix, float grid_size) {
            ImGuizmo::DrawGrid(ColumnMajor(view).m, ColumnMajor(projection).m, ColumnMajor(matrix).m, grid_size);
        },
        nb::arg("view"), nb::arg("projection"), nb::arg("matrix"), nb::arg("grid_size"));
    m.def("draw_grid_custom",
        [](const Matrix& view, const Matrix& projection, const Matrix& matrix, float grid_size, float major_step,
           unsigned int subdivision) {
            ImGuizmo::DrawGridCustom(ColumnMajor(view).m, ColumnMajor(projection).m, ColumnMajor(matrix).m, grid_size,
                                     major_step, subdivision);
        },
        nb::arg("view"), nb::arg("projection"), nb::arg("matrix"), nb::arg("grid_size"), nb::arg("major_step"),
        nb::arg("subdivision"));
    m.def("draw_grid_custom_color",
        [](const Matrix& view, const Matrix& projection, const Matrix& matrix, float grid_size, float major_step,
           unsigned int subdivision, ImU32 major_col, ImU32 minor_col, ImU32 center_col) {
            ImGuizmo::DrawGridCustomColor(ColumnMajor(view).m, ColumnMajor(projection).m, ColumnMajor(matrix).m,
                                          grid_size, major_step, subdivision, major_col, minor_col, center_col);
        },
        nb::arg("view"), nb::arg("projection"), nb::arg("matrix"), nb::arg("grid_size"), nb::arg("major_step"),
        nb::arg("subdivision"), nb::arg("major_col"), nb::arg("minor_col"), nb::arg("center_col"));

    m.def("is_over",
        [](Vec3 position, float pixel_radius) { return ImGuizmo::IsOver(position.data(), pixel_radius); },
        nb::arg("position"), nb::arg("pixel_radius"));
    m.def("compute_mouse_ray",
        [](const Matrix& view, const Matrix& projection, const ImVec2& mouse_position, const ImVec2& rect_position,
           const ImVec2& rect_size) {
            float origin[3], direction[3];
            ImGuizmo::ComputeMouseRay(ColumnMajor(view).m, ColumnMajor(projection).m, mouse_position, rect_position,
                                      rect_size, origin, direction);
            return nb::make_tuple(tuple3(origin), tuple3(direction));
        },
        nb::arg("view"), nb::arg("projection"), nb::arg("mouse_position"), nb::arg("rect_position"),
        nb::arg("rect_size"));
}

